%[text] # **Matlab Vision Based Pick and Place**
%[text] ## **1. Startup (environment)**
% Adding file paths
addpath("Images\")
addpath("Matlab_files\")
addpath("Robodk_files\")

%clear workspace
clc
clear
close all force
% there is no function to clear the output window for the live script
% right-click and select "Clear all output"

% Close a RoboDK instance left open from a previous (interrupted) run, so every run starts from a clean state 
% -- without saving the station.
% IsRoboDKRunning() only probes the port and never launches RoboDK; the Robolink() constructor below is only called 
% if an instance was found, so it just connects to it instead of starting a new one.
if Robolink.IsRoboDKRunning()
    RDK_cleanup = Robolink();
    RDK_cleanup.CloseRoboDK();
    clear RDK_cleanup
    % CloseRoboDK() returns as soon as RoboDK acknowledges the QUIT command, but the process itself can take a moment to actually
    % exit and release the API port. Reconnecting immediately can hit that closing socket (accepted, then reset), so wait until the
    % port is truly free before starting a new instance below.
    t_wait = tic;
    while Robolink.IsRoboDKRunning() && toc(t_wait) < 10
        pause(0.5);
    end
end
%[text] ## **2. Startup (main settings)**
% Setting rdk_status as a global variable to use it with all *.m scripts (speed reasons)
global rdk_status

% Flag: image processing with or without RoboDK
rdk_status = true; %[control:dropdown:498c]{"position":[14,18]}

manual_img_name = "Snap_real_dark.png"; % only used if RoboDK_off %[control:dropdown:108b]{"position":[19,39]}

% Flag: robot motion in simulation or on the real robot
% only used if rdk_status=RoboDK_on
rdk_real_robot = false ; %[control:dropdown:71fe]{"position":[18,23]}

% Starting RoboDK and loading simulation cell
if rdk_status == true
    global RDK; % setting RoboDK as global to use it with all *.m scripts (speed reasons)
%[text] 
    % On a cold start, RoboDK's API port can start accepting TCP connections before its command loop is actually ready to process
    % them, which makes the very first Robolink() call fail with a connection-reset error. Robolink.m's own retry doesn't cover this
    % case (the reset surfaces as a thrown error, not a clean failure), so retry here with a longer delay to give RoboDK time 
    % to finish starting up.
    rdk_connect_attempts = 6;
    for rdk_connect_try = 1:rdk_connect_attempts
        try
            RDK = Robolink(); % starting RoboDK library
            break
        catch RDK_connect_ME
            if rdk_connect_try == rdk_connect_attempts
                rethrow(RDK_connect_ME)
            end
            fprintf("RoboDK ist noch nicht bereit, neuer Verbindungsversuch (%d/%d)...\n", rdk_connect_try, rdk_connect_attempts)
            pause(5)
        end
    end
    
    path_rdk = strcat( pwd , '\Robodk_files\'); % setting RoboDK path
    copyfile Robodk_files\ur5e_station.rdk Robodk_files\ur5e_station_temp.rdk % copy of station to protect against unintended changes
    RDK.AddFile([path_rdk, 'ur5e_station_temp.rdk']); % open RoboDK and station
    
    % Set the RoboDK to simulation or real_robot motion
    RDK.setParam('RUN_MODE', num2str(rdk_real_robot))
    
    % Set image folder for camera
    RDK.setParam('PATH_MATLAB', pwd)
    RDK.setParam('PATH_MATLAB_IMAGES', strcat( pwd , '\Images\'))
    
    % Set simulation or real_robot motion
    if rdk_real_robot == false
        RDK.setRunMode(RDK.RUNMODE_SIMULATE)
    else
        RDK.setRunMode(RDK.RUNMODE_RUN_ROBOT) % !! not working yet !! (You can not call py-Programm in real mode :( )
    end
    
    %robot = RDK.Item('UR5e'); % select UR5e node in RoboDK
    %robot.Disconnect()

    robot = RDK.Item('UR5e'); % select UR5e node in RoboDK
    if rdk_real_robot == 1
        robot.Connect()
    end
    RDK.setSimulationSpeed(0.5) % set simulation speed
end
%[text] ## **3. Image generation**
%[text] Taking a picture from RoboDK: either in the simulated or the real environment (for details, see the Python code in RoboDK).
%[text] Then display the raw image in Matlab.
% Move the robot to default picture position and take a picture
if rdk_status == true %[output:group:7826cbb0]
    RDK_Ur5e_HOME() % move robot to default picture position %[output:203ee06a]
    RDK_REALSENSE_SNAP() % take picture %[output:6a838dd3]
    % set simulation or real_robot as picture input
    if rdk_real_robot == true
        im = im2single(imread('Snap_real.jpg'));
    else
        im = im2single(imread('Snap_sim.jpg'));
    end
else
    % No RoboDK, we work on a stored image
    im = im2single(imread(manual_img_name));
end %[output:group:7826cbb0]

disp("Camera image (raw)") %[output:1b8563a4]
f1 = figure; imshow(im); title('Camera image (raw)'); %[output:5aa9287c]
%disp(RDK.ItemList())
%[text] ## **4. Image processing**
%[text] Optimize the previously loaded raw image for better detection of the RGB colours.
% Split image in R/G/B values and display output
[R,G,B] = imsplit(im);
disp("Split image in R/G/B") %[output:3b79c34b]
montage({R,G,B},'Size',[1 3]) %[output:4a0d1241]

disp("Adjust brightness in low-light areas") %[output:7fb44bc1]
im_rgbadj = imlocalbrighten(im);
imshowpair(im,im_rgbadj,"montage");

disp("Camera image (RGB adjusted)") %[output:0918eb54]
f2 = figure; imshow(im_rgbadj); title('Camera image (RGB adjusted)');

% Use the adjusted image from now on
im = im_rgbadj;

% Grayscale in R/G/B and display
% red
r = R ./(R+G+B); % see help "rdivide, ./"
f3 = placeFig([1 1], 'HistImage', r, 'Name','Grey scale (R)','WindowStyle','normal','Visible','on'); %[output:079a1ff4]
imshow(r); title('Grey scale (R)'); impixelinfo; drawnow; %[output:079a1ff4]
% green
g = G ./(R+G+B);
f4 = placeFig([1 2], 'HistImage', g, 'Name','Grey scale (G)','WindowStyle','normal','Visible','on'); %[output:4d77d1d5]
imshow(g); title('Grey scale (G)'); impixelinfo; drawnow; %[output:4d77d1d5]
% blue
b = B ./(R+G+B);
f5 = placeFig([1 3], 'HistImage', b, 'Name','Grey scale (B)','WindowStyle','normal','Visible','on'); %[output:5edddaa5]
imshow(b); title('Grey scale (B)'); impixelinfo; drawnow; %[output:5edddaa5]

% Define threshold for the color and display resulting image
% black is 0, white is 1
% red
r_thresh = r>0.44; % see help "gt, >" 
f6 = placeFig([2 1], 'Name','Binary Image (R)','WindowStyle','normal','Visible','on'); %[output:337fad34]
imshow(r_thresh); title('Binary Image (R)'); %[output:337fad34]
% green
g_thresh = g>0.40;
f7 = placeFig([2 2], 'Name','Binary Image (G)','WindowStyle','normal','Visible','on'); %[output:998ab0bc]
imshow(g_thresh); title('Binary Image (G)'); %[output:998ab0bc]
% blue
b_thresh = b>0.38;
f8 = placeFig([2 3], 'Name','Binary Image (B)','WindowStyle','normal','Visible','on'); %[output:99858f6d]
imshow(b_thresh); title('Binary Image (B)'); %[output:99858f6d]
%[text] Generate the center for each object (colored blocks) and display it.
% display image to mark the detected objects
f9 = placeFig('center', 'Name','Gripper poses','WindowStyle','normal','Visible','on'); %[output:7482d2b1]
imshow(im); title('Gripper poses'); %[output:7482d2b1]

% some common drawing properties
markersize = 15;
linewidth = 1.5;
or_extension = 1.5;

% Red - detect object and draw properties
try %[output:group:98cdc0a4]
    figure(f9); % ensure ellipses/markers are drawn onto the Gripper poses image
    m_red = imblobs(r_thresh,'area',[500,50000]);
    m_red.plot_ellipse('edgecolor','k','LineWidth', linewidth); %[output:7482d2b1]
    m_red.plot('s', 'MarkerSize', markersize, 'MarkerFaceColor','r', 'MarkerEdgeColor','w','LineWidth', linewidth); %[output:7482d2b1]
    
    % center of first red object
    x_m_red = m_red(1).uc;
    y_m_red = m_red(1).vc;
    m_red_center = [ x_m_red ; y_m_red ];
    
    % drawing orientation
    x_min = x_m_red - cos(m_red(1).theta_)*m_red(1).a*or_extension;
    x_max = x_m_red + cos(m_red(1).theta_)*m_red(1).a*or_extension;
    y_min = y_m_red - sin(m_red(1).theta_)*m_red(1).a*or_extension;
    y_max = y_m_red + sin(m_red(1).theta_)*m_red(1).a*or_extension;
    line( [x_min x_max], [y_min y_max], 'Color', 'k', 'LineWidth', linewidth ); %[output:7482d2b1]
    
    disp("Red block found.") %[output:068de1b7]
catch ME
    disp("No red block found!")
end %[output:group:98cdc0a4]

% Green - detect object and draw properties
try %[output:group:00fdf89e]
    figure(f9); % ensure ellipses/markers are drawn onto the Gripper poses image
    m_green = imblobs(g_thresh,'area',[500,50000]);
    m_green.plot_ellipse('edgecolor','k','LineWidth', linewidth); %[output:7482d2b1]
    m_green.plot('d', 'MarkerSize', markersize, 'MarkerFaceColor','g', 'MarkerEdgeColor','w', 'LineWidth', linewidth); %[output:7482d2b1]
    
    % center of first green object
    x_m_green = m_green(1).uc;
    y_m_green = m_green(1).vc;
    m_green_center = [ x_m_green ; y_m_green ];
   
    % drawing orientation
    x_min = x_m_green - cos(m_green(1).theta)*m_green(1).a*or_extension;
    x_max = x_m_green + cos(m_green(1).theta)*m_green(1).a*or_extension;
    y_min = y_m_green - sin(m_green(1).theta)*m_green(1).a*or_extension;
    y_max = y_m_green + sin(m_green(1).theta)*m_green(1).a*or_extension;
    line( [x_min x_max], [y_min y_max], 'Color', 'k', 'LineWidth', linewidth ); %[output:7482d2b1]
    
    disp("Green block found.") %[output:7254bab7]
catch ME
    disp("No green block found!")
end %[output:group:00fdf89e]

% Blue - detect object and draw properties
try %[output:group:6dd249e8]
    figure(f9); % ensure ellipses/markers are drawn onto the Gripper poses image
    m_blue = imblobs(b_thresh,'area',[500,50000]);
    m_blue.plot_ellipse('edgecolor','k','LineWidth', linewidth); %[output:7482d2b1]
    m_blue.plot('o', 'MarkerSize', markersize, 'MarkerFaceColor','b', 'MarkerEdgeColor','w', 'LineWidth', linewidth); %[output:7482d2b1]
    
    % center of first blue object
    x_m_blue = m_blue(1).uc;
    y_m_blue = m_blue(1).vc;
    m_blue_center = [ x_m_blue ; y_m_blue ];
    
    % drawing orientation
    x_min = x_m_blue - cos(m_blue(1).theta)*m_blue(1).a*or_extension;
    x_max = x_m_blue + cos(m_blue(1).theta)*m_blue(1).a*or_extension;
    y_min = y_m_blue - sin(m_blue(1).theta)*m_blue(1).a*or_extension;
    y_max = y_m_blue + sin(m_blue(1).theta)*m_blue(1).a*or_extension;
    line( [x_min x_max], [y_min y_max], 'Color', 'k', 'LineWidth', linewidth ); %[output:7482d2b1]
    
    disp("Blue block found.") %[output:278a4708]
catch ME
    disp("No blue block found!")
end %[output:group:6dd249e8]

% Camera raw / RGB adjusted previews are not needed for the adjustment
% workflow anymore, close them before arranging the remaining windows
close(f1);
close(f2);

%[text] ## **5. Robot simulation in RoboDK (with Homography)**
%[text] Update the RoboDK cell with the calculated position. Therefore you have to do first a 2D to 2D transformation (homography).
if rdk_status == true
    % H_sim: homography matrix for the simulation environment
    % homography with 4 points on a plane
    % image                        simulation_world
    % camera_calibration/Top_L:
        i1 = [ 142 ,  124 ];      w1 = [   29 , -473 ];
    % camera_calibration/Top_R:
        i2 = [ 439 ,  124 ];      w2 = [ -209 , -473 ];
    % camera_calibration/Bot_L:
        i3 = [ 156 ,  327 ];      w3 = [   29 , -296 ];
    % camera_calibration/Bot_R:
        i4 = [ 428 ,  327 ];      w4 = [ -209 , -296 ];
    % generating the homography matrix
    p1 = [i1(1), i2(1), i3(1), i4(1); i1(2), i2(2), i3(2), i4(2)];
    p2 = [w1(1), w2(1), w3(1), w4(1); w1(2), w2(2), w3(2), w4(2)];
    % homography matrix in the simulated world
    H_sim = homography(p1, p2);
    

    % H_real: homography matrix for the real world
    % image
    % camera_calibration/Top_L:
        i1 = [ 143,   75];      w1 = [  47.43, -515.40];
    % camera_calibration/Top_R:
        i2 = [ 658,   72];      w2 = [-273.43, -511.60];
    % camera_calibration/Bot_L:
        i3 = [ 170,  320];      w3 = [  48.20, -287.26];
    % camera_calibration/Bot_R:
        i4 = [ 626,  320];      w4 = [-273.43, -285.10];
    % generating the homography matrix
    p1 = [i1(1), i2(1), i3(1), i4(1); i1(2), i2(2), i3(2), i4(2)];
    p2 = [w1(1), w2(1), w3(1), w4(1); w1(2), w2(2), w3(2), w4(2)];
    % homography matrix in the simulated world
    H_real = homography(p1, p2);
    
    if rdk_real_robot == 1
        H_used = H_real;
    else
        H_used = H_sim;
    end
    
    % distance above the table to grip the block
    z_grip = 3.5;
    
    % Red block
    try
        % Calculate center point in world coordinates 
        m_red_center_sim = homtrans(H_used,m_red_center); 
        
        % Transition matrix with translation only
        T_red_1 = [ 1, 0, 0, m_red_center_sim(1);
        	        0, 1, 0, m_red_center_sim(2);
        	        0, 0, 1, z_grip;
        	        0, 0, 0, 1                    ];
        
        % Transition matrix with orientation
        T_red_2 = T_red_1 * rotz(-1 * m_red(1).theta);
        
        % Updating the RDK frame
        Frame = RDK.Item('red_part_calculated_frame');
        Frame.setPose( T_red_2 );
    catch ME
        disp("No red block found!")
    end
    
    % Green block
    try
        % Calculate center point in world coordinates 
        m_green_center_sim = homtrans(H_used,m_green_center); 
        
        % Transition matrix with translation only
        T_green_1 = [ 1, 0, 0, m_green_center_sim(1);
        	          0, 1, 0, m_green_center_sim(2);
        	          0, 0, 1, z_grip;
        	          0, 0, 0, 1                    ];
        
        % Transition matrix with orientation
        T_green_2 = T_green_1 * rotz(-1 * m_green(1).theta);
        
        % Updating the RDK frame
        Frame = RDK.Item('green_part_calculated_frame');
        Frame.setPose( T_green_2 );
    catch ME
        disp("No green block found!")
    end
    
    % Blue block
    try
        % Calculate center point in world coordinates 
        m_blue_center_sim = homtrans(H_used,m_blue_center); 
        
        % Transition matrix with translation only
        T_blue_1 = [ 1, 0, 0, m_blue_center_sim(1);
        	         0, 1, 0, m_blue_center_sim(2);
        	         0, 0, 1, z_grip;
        	         0, 0, 0, 1                    ];
        
        % Transition matrix with orientation
        T_blue_2 = T_blue_1 * rotz(-1 * m_blue(1).theta);
        
        % Updating the RDK frame
        Frame = RDK.Item('blue_part_calculated_frame');
        Frame.setPose( T_blue_2 );
    catch ME
        disp("No blue block found!")
    end

end
%%
%[text] The following code performs robot motion in the RoboDK simulation environment.
%[text] **NOTE: motions are not optimised and may cause collisions in the real world!**
if rdk_status == true %[output:group:1b862eda]
    % Go to the home position (defined in RoboDK) and open the gripper
    %Go_home()
    %Open_gripper('_')
    RDK_Ur5e_HOME() %[output:2ddfdef4]
    RDK_HandE_DO("activate",["" ""]) %[output:46d1671d]
    RDK_HandE_DO("open",["" ""]) %[output:0c85fe93]
    
    % Pick the red block
    RDK_Ur5e_MoveL('app_red_calculated_target');
    RDK_Ur5e_MoveL('pick_red_calculated_target');
    RDK_HandE_DO("open_20mm",["pick" "red"]) %[output:4a5a236f]
    RDK_Ur5e_MoveL('app_red_calculated_target');
    
    % Place the red block
    RDK_Ur5e_MoveL('app_place_target');
    RDK_Ur5e_MoveL('place_red_target');
    RDK_HandE_DO("open",["place" "red"]) %[output:8e70357a]
    RDK_Ur5e_MoveL('app_place_target');
    
    % Pick the green block
    RDK_Ur5e_MoveL('app_green_calculated_target');
    RDK_Ur5e_MoveL('pick_green_calculated_target');
    RDK_HandE_DO("open_20mm",["pick" "green"]) %[output:9e85b58e]
    RDK_Ur5e_MoveL('app_green_calculated_target');
    
    % Place the green block
    RDK_Ur5e_MoveL('app_place_target');
    RDK_Ur5e_MoveL('place_green_target');
    RDK_HandE_DO("open",["place" "green"]) %[output:952e4a36]
    RDK_Ur5e_MoveL('app_place_target');
    
    % Pick the blue block
    RDK_Ur5e_MoveL('app_blue_calculated_target');
    RDK_Ur5e_MoveL('pick_blue_calculated_target');
    RDK_HandE_DO("open_20mm",["pick" "blue"]) %[output:641d961a]
    RDK_Ur5e_MoveL('app_blue_calculated_target');
    
    % Place the blue block
    RDK_Ur5e_MoveL('app_place_target');
    RDK_Ur5e_MoveL('place_blue_target');
    RDK_HandE_DO("open",["place" "blue"]) %[output:2ecc717f]
    RDK_Ur5e_MoveL('app_place_target');
    
    % Go to the home position and open gripper
    RDK_Ur5e_HOME() %[output:5e7db212]
    RDK_HandE_DO("open",["" ""]) %[output:120ba952]
    %
    robot.Disconnect();

end %[output:group:1b862eda]

